def solve():
    def get_max_sum(a):
        n = len(a)
        # dp[i] = max sum of a subsequence ending at index i
        # such that the gap between consecutive indices is at most 2.
        dp = [0] * n
        for i in range(n):
            dp[i] = a[i]
            if i >= 1:
                dp[i] = max(dp[i], dp[i-1] + a[i])
            if i >= 2:
                dp[i] = max(dp[i], dp[i-2] + a[i])
        return max(dp) if dp else 0

    # But we want the max absolute sum, so we should also consider -a.
    def get_max_abs_sum(a):
        return max(get_max_sum(a), -get_max_sum([-x for x in a]))

    # To find C for a given n, we need to find the minimum over all a of get_max_abs_sum(a)
    # Since we want the maximum C such that for any a there exists a sum >= C,
    # we need the minimum over all a of the maximum absolute sum.

    # Let's try small n.
    import itertools
    results = []
    for n in range(1, 11):
        min_max_abs_sum = float('inf')
        # Generate all +/- 1 sequences
        for a in itertools.product([1, -1], repeat=n):
            max_abs_sum = get_max_abs_sum(list(a))
            if max_abs_sum < min_max_abs_sum:
                min_max_abs_sum = max_abs_sum
        results.append(min_max_abs_sum)
        print(f"n={n}, C={min_max_abs_sum}")

