def get_max_sum(a):
    n = len(a)
    # dp[i] = max sum of a subsequence ending at index i
    # such that the gap between consecutive indices is at most 2.
    # This DP only works if the subsequence *must* end at i.
    dp = [0] * n
    for i in range(n):
        dp[i] = a[i]
        if i >= 1:
            dp[i] = max(dp[i], dp[i-1] + a[i])
        if i >= 2:
            dp[i] = max(dp[i], dp[i-2] + a[i])
    return max(dp)

def get_max_abs_sum(a):
    # We need the maximum absolute sum of any valid subsequence.
    # A subsequence is valid if the gap between consecutive indices is at most 2.
    # Let dp_max[i] be the maximum sum of a valid subsequence ending at index i.
    # Let dp_min[i] be the minimum sum of a valid subsequence ending at index i.
    n = len(a)
    dp_max = [0] * n
    dp_min = [0] * n
    for i in range(n):
        dp_max[i] = a[i]
        dp_min[i] = a[i]
        if i >= 1:
            dp_max[i] = max(dp_max[i], dp_max[i-1] + a[i])
            dp_min[i] = min(dp_min[i], dp_min[i-1] + a[i])
        if i >= 2:
            dp_max[i] = max(dp_max[i], dp_max[i-2] + a[i])
            dp_min[i] = min(dp_min[i], dp_min[i-2] + a[i])
    return max(max(dp_max), -min(dp_min))

